/** ภาพหน้าจอจริงจาก assets/guide/ (ถ่ายใหม่ได้ด้วย tools/guide-shots.mjs) · ใส่ขนาดจริงกันหน้ากระโดด · lazy */
function shot(string $name, string $alt, string $caption = '', string $class = ''): string {
    $file = APP_ROOT . '/assets/guide/' . $name . '.webp';
    if (!is_file($file)) return '';
    $size = @getimagesize($file) ?: [1100, 620];
    return '<figure class="shot ' . h($class) . '"><img src="assets/guide/' . h($name) . '.webp?v=' . (int) filemtime($file) . '" width="' . (int) $size[0] . '" height="' . (int) $size[1]
        . '" alt="' . h($alt) . '" loading="lazy" decoding="async">' . ($caption !== '' ? '<figcaption>' . $caption . '</figcaption>' : '') . '</figure>';
}
/** กล่อง "ครูบูรณ์แนะนำ" หัวมีภาพครึ่งตัว 40px (BRAND-MASCOT 6.3) · ยังไม่มีภาพ = เหลือหัวข้อความ */
function tip(string $html): string {
    static $bust = null;
    $bust ??= mascot_img('boon-bust-160.webp', 160, 160, 'tip-bust');
    return '<div class="tip"><p class="tip-h">' . $bust . '<b>ครูบูรณ์แนะนำ</b></p>' . $html . '</div>';
}
